from pathlib import Path
from html import escape as esc
from urllib.parse import quote
import json,shutil,csv,hashlib,re
from PIL import Image
from functools import lru_cache
P=Path(__file__).resolve().parent;D=P/'.generated-pages'
COPY=json.loads((P/'content/team-copy.json').read_text())['team_text']
S=json.loads((P/'content/site.json').read_text());T=json.loads((P/'content/team.json').read_text());PARTNERS=json.loads((P/'content/partners.json').read_text())
def e(v):return esc(str(v),quote=True)
@lru_cache(maxsize=None)
def image_size(file):
 try:
  path=P.parent/'public/rewrite'/file.split('?')[0].lstrip('/')
  if path.suffix=='.svg':
   import xml.etree.ElementTree as ET
   box=ET.parse(path).getroot().get('viewBox','0 0 100 100').split();return round(float(box[2])),round(float(box[3]))
  with Image.open(path) as im:return im.size
 except (OSError,ValueError):return None
RESPONSIVE=json.loads((P/'content/responsive-images.json').read_text()) if (P/'content/responsive-images.json').exists() else {}
def img(file,alt,cls='',lazy=True):
 size=image_size(file);dimensions=f' width="{size[0]}" height="{size[1]}"' if size else ''
 variants=RESPONSIVE.get(file,[])
 sizes='(max-width:700px) 50vw, 300px' if '/team/' in file else '(max-width:700px) 90vw, 640px'
 srcset=' srcset="'+', '.join(f'{x["src"]} {x["width"]}w' for x in variants)+'" sizes="'+sizes+'"' if variants else ''
 source=next((x['src'] for x in variants if x['width']>=640),variants[-1]['src']) if variants else file
 priority='high' if not lazy and file in ['/assets/volunteers.webp','/assets/logo.webp'] else 'low' if lazy else 'auto'
 return f'<img src="{e(source)}" alt="{e(alt)}" class="{cls}" loading="eager" decoding="async"{dimensions}{srcset} fetchpriority="{priority}">'

def kit_asset(file):return file+'?v='+hashlib.sha256((P.parent/'public/rewrite'/file.lstrip('/')).read_bytes()).hexdigest()[:10]
def btn(text,href,style='pink',extra=''):return f'<a class="button {style}" href="{e(href)}" {extra}>{text}</a>'
def icon(name):
 paths={
 'notebook':'<rect x="8" y="4" width="23" height="32" rx="2"/><path d="M5 10h6M5 17h6M5 24h6M5 31h6M17 12h8M17 18h8M17 24h6"/>',
 'folder':'<path d="M4 10l15-5 17 5v25l-17-6-15 6zM19 5v24M4 22l15-5 17 5"/>',
 'pencils':'<path d="M6 14l4-9 4 9v21H6zM17 14l4-9 4 9v21h-8zM28 14l4-9 4 9v21h-8zM6 14h8M17 14h8M28 14h8"/>',
 'pens':'<path d="M6 34V17l5-12 5 12v17M6 26h10M6 17l5 4 5-4M24 34V20l-3-6 8-10 8 10-3 6v14M29 4v11M27 24h7"/>',
 'copy':'<rect x="14" y="13" width="19" height="23" rx="3"/><path d="M25 13V7a3 3 0 0 0-3-3H8a3 3 0 0 0-3 3v19a3 3 0 0 0 3 3h6"/>',
 'arrow':'<path d="M8 20h24M23 11l9 9-9 9"/>',
 'search':'<circle cx="17" cy="17" r="10"/><path d="m25 25 10 10"/>',
 'chevron':'<path d="M10 15l10 10 10-10"/>',
 'leaf':'<path d="M7 32C-1 16 13 6 34 5c1 19-8 34-23 27M7 35l20-21"/>',
 'heart':'<path d="M20 34S3 23 3 13C3 2 17 1 20 10 23 1 37 2 37 13c0 10-17 21-17 21z"/>',
 'people':'<circle cx="13" cy="12" r="5"/><circle cx="29" cy="12" r="5"/><path d="M3 34V24c0-8 20-8 20 0v10M23 20c7-4 14 0 14 5v9"/>',
 'box':'<path d="M4 12l16-8 16 8-16 9zM4 12v19l16 7 16-7V12M20 21v17M12 8l16 9"/>'}
 return f'<svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{paths.get(name,paths["arrow"])}</svg>'
def social():
 paths={
 'facebook':'<path d="M13.5 22v-9h3l.5-3.5h-3.5V7.25c0-1 .3-1.75 1.8-1.75H17V2.3a22 22 0 0 0-2.7-.15c-2.7 0-4.55 1.65-4.55 4.7V9.5H7V13h2.75v9z"/>',
 'instagram':'<rect x="3" y="3" width="18" height="18" rx="5" fill="none" stroke="currentColor" stroke-width="1.8"/><circle cx="12" cy="12" r="4.25" fill="none" stroke="currentColor" stroke-width="1.8"/><circle cx="17.5" cy="6.5" r="1.1"/>',
 'linkedin':'<path d="M4 9h3.5v12H4zM10 9h3.4v1.65c.5-.95 1.75-1.95 3.55-1.95 3.8 0 4.05 2.45 4.05 5.65V21h-3.5v-5.9c0-1.45-.05-3.3-2-3.3s-2.1 1.55-2.1 3.2v6H10z"/><circle cx="5.75" cy="4.7" r="2"/>'}
 return ''.join(f'<a href="{e(url)}" aria-label="The Re-Write It Project on {name.title()}" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor">{paths[name]}</svg></a>' for name,url in S['social'].items())
def header(active):
 about_pages=[('about','Our story'),('impact','Our impact'),('team','Our team'),('get-involved','Get involved'),('contact','Contact us')]
 in_about=active in [route for route,label in about_pages]+['join']
 links=''.join(f'<a href="/{route}/"'+(' aria-current="page"' if active==route else '')+f'>{label}</a>' for route,label in about_pages)
 return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="header-inner"><a class="brand" href="/" aria-label="The Re-Write It Project home">{img('/assets/logo.webp','','brand-mark',False)}<span>The Re-Write It Project</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav" aria-label="Open navigation"><span></span><span></span><span></span></button><nav id="main-nav" class="main-nav" aria-label="Main navigation"><div class="nav-dropdown"><button class="nav-dropdown-toggle{' is-current' if in_about else ''}" aria-expanded="false" aria-controls="about-menu">About us {icon('chevron')}</button><div class="dropdown-menu" id="about-menu">{links}</div></div><a href="/chapters/" {'aria-current="page"' if active=='chapters' else ''}>Start a chapter</a><a href="/receive/" {'aria-current="page"' if active=='receive' else ''}>Receive</a><a href="{e(S['donation_url'])}" class="nav-give" {'aria-current="page"' if active=='give' else ''}>Give</a></nav></div></header>'''

D.mkdir(exist_ok=True)
PHOTOS={p["id"]:p for p in json.loads((P/"content/photos.json").read_text())}

def donation_widget(context='home'):
 return f'''<form class="donation-picker" action="{e(S['donation_url'])}" method="get" target="_blank" rel="noopener" aria-label="Choose your donation amount"><fieldset><legend class="sr-only">Donation amount</legend><div class="amount-options"><button type="button" class="amount-choice" data-amount="5" aria-pressed="false"><strong>$5</strong><small>One kit</small></button><button type="button" class="amount-choice" data-amount="50" aria-pressed="false"><strong>$50</strong><small>10 kits</small></button><button type="button" class="amount-choice" data-amount="100" aria-pressed="false"><strong>$100</strong><small>20 kits</small></button><label class="custom-choice"><span class="custom-input"><span>$</span><input type="number" data-custom min="1" max="100000" step="0.01" inputmode="decimal" aria-label="Custom donation amount"></span><small>Custom</small></label></div></fieldset><input type="hidden" name="amount" value="" disabled><input type="hidden" name="default_interval" value="o"><button type="submit" class="button pink">Donate</button><span class="form-error" aria-live="polite"></span></form>'''

def involvement():
 return f'''<section class="home-involved blue-section"><h2>Want to get involved?</h2><div class="involvement-grid">{''.join(f'<article class="involvement-card"><div class="involvement-heading"><h3>{title}</h3></div><p>{copy}</p>{btn(label,url,"white")}</article>' for n,title,copy,label,url in [('1','Start a<br>chapter','Opening a chapter of The Re-Write It Project is easy! Learn more here:','Start a chapter','/chapters/'),('2','Make a<br>donation','Just <span data-site-price>$5</span> covers an entire kit for a student. Make an impact today!','Donate here',S['donation_url']),('3','Partner<br>with us','Our community partners are the reason we can do what we do. Contact us:','Contact','/contact/')])}</div></section>'''

