def privacy():
 return '<section class="privacy-copy wrap">'+page_intro('Privacy','How this website handles the information you share.')+f'<h2>Contact forms and applications</h2><p>When you submit a contact message, supply request, or volunteer application, we send your name, email address, and the details you provide to therewriteitproject@gmail.com through FormSubmit. FormSubmit processes the form details to deliver that email. We use this information to review your request and respond to you. We do not publish it.</p><p>Please do not include personal information about individual students. To ask about correcting or removing a message you have submitted, email <a href="mailto:{S["email"]}">{S["email"]}</a></p><h2>Donations</h2><p>Donation links open the nonprofit’s campaign on Donorbox, which processes payments through its secure form. See <a href="https://donorbox.org/privacy" target="_blank" rel="noopener noreferrer">Donorbox’s privacy policy</a> for information about its service.</p><h2>Chapter applications</h2><p>The chapter application opens in Google Forms and is handled through that service.</p><h2>Cookies and website tools</h2><p>This website does not use advertising trackers. When you follow links to Donorbox or Google Forms, those services may use their own cookies.</p></section>'
def received():
 return '<section class="receipt-page wrap"><p class="section-label">The Re-Write It Project</p><h1>Message received</h1><p>Thank you for contacting our team. Your message has been submitted.</p><p>The team can review it and contact you at the email address you provided.</p>'+btn('Return to the homepage','/')+'</section>'
def with_email_copy_controls(html):
 def add(match):
  address=match.group(1)
  return '<span class="email-copy-link">'+match.group(0)+f'<button type="button" class="email-copy-button" data-copy-email="{e(address)}" aria-label="Copy {e(address)}" title="Copy email address">{icon("copy")}</button><span class="copy-status sr-only" role="status"></span></span>'
 html=re.sub(r'(<a\b[^>]*href="mailto:[^"]+"[^>]*>.*?</a>)\.(?=\s*</p>)',r'\1',html)
 return re.sub(r'<a\b[^>]*href="mailto:([^"]+)"[^>]*>.*?</a>',add,html)
